import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"工業工程與管理系 — 課程筆記","description":"","frontmatter":{},"headers":[],"relativePath":"entities/ie-department.md","filePath":"entities/ie-department.md"}'),r={name:"entities/ie-department.md"};function o(n,l,s,h,d,p){return a(),e("div",null,[...l[0]||(l[0]=[t('<h1 id="工業工程與管理系-—-課程筆記" tabindex="-1">工業工程與管理系 — 課程筆記 <a class="header-anchor" href="#工業工程與管理系-—-課程筆記" aria-label="Permalink to &quot;工業工程與管理系 — 課程筆記&quot;">​</a></h1><p>來源: <code>02.學習/工業工程與管理系/</code></p><p>北科大工業工程與管理系課程筆記，涵蓋決策分析、作業研究、專案管理、顧客關係管理等科目。</p><h2 id="決策分析-洪子晏-2021" tabindex="-1">決策分析 (洪子晏 2021) <a class="header-anchor" href="#決策分析-洪子晏-2021" aria-label="Permalink to &quot;決策分析 (洪子晏 2021)&quot;">​</a></h2><p>完整課程大綱與 17 週進度。決策理論基本觀念與真實世界應用。</p><p><strong>核心主題:</strong></p><ul><li>不考慮機率的決策問題</li><li>與機率有關的決策問題</li><li>貝氏分析與貝氏網路</li><li>效益分析 (Utility Theory)</li><li>遊戲理論 (Game Theory)</li><li>風險下的決策與資訊價值</li></ul><p><strong>偏差類型筆記 (大量):</strong></p><ul><li>代表性偏差、局部思考偏差、框架效應、基準點偏差</li><li>過度自信、附和偏差、保守偏差、既存狀態偏差</li><li>近期偏差、隨機偏差、推論偏差、尋求滿足偏差</li><li>想討好每一個人、忽視偏差、沒有找對問題偏差</li></ul><p><strong>決策分類維度:</strong></p><ul><li>理性 vs 非理性 vs 有限理性</li><li>規範、處方或敘述</li><li>結構化、半結構化、非結構化</li><li>深思熟慮 vs 及時決定</li><li>預期或偶發</li><li>經常面臨或獨特</li></ul><p><strong>實用框架:</strong></p><ul><li>決策山 (勢)、SMART 法、TRIZ 萃思法</li><li>系統化決策流程</li><li>利害關係人分析</li></ul><h2 id="作業研究" tabindex="-1">作業研究 <a class="header-anchor" href="#作業研究" aria-label="Permalink to &quot;作業研究&quot;">​</a></h2><ul><li>連通 (Connected Graph)</li><li>網路 (Network)</li><li>網路模式 (Network Models)</li></ul><h2 id="專案管理-2022-03-14" tabindex="-1">專案管理 (2022-03-14) <a class="header-anchor" href="#專案管理-2022-03-14" aria-label="Permalink to &quot;專案管理 (2022-03-14)&quot;">​</a></h2><p>專案管理課程筆記，日期記錄。</p><h2 id="顧客關係管理" tabindex="-1">顧客關係管理 <a class="header-anchor" href="#顧客關係管理" aria-label="Permalink to &quot;顧客關係管理&quot;">​</a></h2><ul><li>重要顧客</li><li>資訊技術</li><li>管理架構</li><li>顧客互動模式</li></ul><h2 id="面試重點" tabindex="-1">面試重點 <a class="header-anchor" href="#面試重點" aria-label="Permalink to &quot;面試重點&quot;">​</a></h2><p><strong>生產與品質管理:</strong></p><ul><li>生產方式: 零工式、批量式、裝配線式、連續式</li><li>工廠佈置: 程序、產品、固定位置、單元式</li><li>產能規劃: 設計產能、有效產能、實際產出</li><li>瓶頸分析、甘特圖、CPM/PERT、派工法則</li><li>利特爾法則 (Little&#39;s Law): WIP = Throughput × Lead Time</li><li>精實生產: 七大浪費、拉式系統、看板</li></ul><p><strong>品質管理:</strong></p><ul><li>戴明 PDCA、朱蘭品質三部曲、克勞斯比零缺點、石川馨品質圈</li><li>品質成本 (COQ): 預防、鑑定、內部失敗、外部失敗</li><li>QC 七大手法、SPC 管制圖、ISO 9001 <strong>統計學:</strong> 面試重點整理</li></ul><h2 id="電子或紙本" tabindex="-1">電子或紙本 <a class="header-anchor" href="#電子或紙本" aria-label="Permalink to &quot;電子或紙本&quot;">​</a></h2><p>關於學習方式的個人偏好筆記。</p>',26)])])}const m=i(r,[["render",o]]);export{c as __pageData,m as default};
